from collections import deque,defaultdict
H,W=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(H):
 for c in range(W):
  col=grid[r][c]
  if col==1 or (r,c) in seen: continue
  q=[(r,c)]; seen.add((r,c)); cells=[]
  while q:
   y,x=q.pop(); cells.append((y,x))
   for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
    yy,xx=y+dy,x+dx
    if 0<=yy<H and 0<=xx<W and grid[yy][xx]==col and (yy,xx) not in seen:
     seen.add((yy,xx)); q.append((yy,xx))
  rs=[a for a,b in cells]; cs=[b for a,b in cells]
  comps.append((col,len(cells),(min(rs),min(cs),max(rs),max(cs)),any(y in(0,H-1) or x in(0,W-1) for y,x in cells),cells))
[(co,n,box,edge) for co,n,box,edge,_ in comps]

